private processRequestWithToken(token: string, req:
HttpRequest<any>,
next: HttpHandler) {
if (!!token && this.isSameOriginUrl(req)) {
req = req.clone({
setHeaders: {
Authorization: `Bearer ${token}`
}
});
}
return next.handle(req);
}
private isSameOriginUrl(req: any) {
// It's an absolute url with the same origin.
if (req.url.startsWith(`${window.location.origin}/`)) {
return true;
}
// It's a protocol relative url with the same origin.
// For example: //www.example.com/api/Products
if (req.url.startsWith(`//${window.location.host}/`)) {
return true;
}
// It's a relative url like /api/Products
if (/^\/[^\/].*/.test(req.url)) {
return true;
}
// It's an absolute or protocol relative url that
// doesn't have the same origin.
return false;
}
}
As we can see, the AuthorizeInterceptor implements the HttpInterceptor
interface by defining an intercept method. That method's job is to intercept all the
outgoing HTTP requests and conditionally add the JWT Bearer token to their HTTP
headers; this condition is determined by the isSameOriginUrl() internal method,
which will return true only if the request is addressed to an URL with the same
origin of the Angular app.
